def esc(x): return H.escape(str(x), quote=False)
def rich(x): return str(x)

def tile(t):
    tone = t.get("tone", "")
    cls = {"up": "pos", "down": "neg", "": "mut"}.get(tone, "mut")
    vcls = ' neg' if t.get("value_red") else ''
    w = '' if tone else ' style="font-weight:500"'
    return (f'<div class="card"><p class="lab">{esc(t["label"])}</p><p class="v{vcls}">{esc(t["value"])}</p>'
            f'<p class="chg {cls}"{w}>{esc(t.get("note",""))}</p></div>')

def chips(cs):
    out = ""
    for sym, pct in cs:
        c = "pos" if str(pct).startswith("+") else ("neg" if str(pct).startswith(("−", "-")) else "")
        out += f'<span class="chip {c}">{esc(sym)} {esc(pct)}</span>'
    return out

def news(items):
    m = {"+": ("tg", "Tích cực"), "-": ("tr", "Tiêu cực"), "o": ("tn", "Theo dõi")}
    return "".join(f'<p><span class="tag {m[i["s"]][0]}">{m[i["s"]][1]}</span>{chips(i.get("chips", []))}{rich(i["text"])}</p>' for i in items)

def hero(d):
    h = d.get("hero")
    if not h: return ""
    ch = "".join(("" if n == 0 else '<div class="ar">→</div>') + f'<div class="st">{rich(x)}</div>' for n, x in enumerate(h.get("chain", [])))
    chain = f'<div class="chain">{ch}</div>' if ch else ""
    return (f'<div class="hero"><div class="row"><div><div class="big">{esc(h["big"])}</div><div class="bl">{esc(h["label"])}</div></div>'
            f'<div class="tx">{rich(h["text"])}</div></div>{chain}</div>')

def week(d):
    import datetime
    dd, mm, yy = (int(x) for x in d["file_date"].split("-"))
    mon = datetime.date(yy, mm, dd); mon -= datetime.timedelta(days=mon.weekday())
    names = ["Thứ Hai", "Thứ Ba", "Thứ Tư", "Thứ Năm", "Thứ Sáu"]
    by = {}
    for kind, rows in (("c", d.get("dividends", [])), ("e", d.get("events", []))):
        for r in rows: by.setdefault(r[0], []).append((kind, r[1], r[2]))
    cols = ""
    for i in range(5):
        day = mon + datetime.timedelta(days=i); key = day.strftime("%d/%m")
        its = "".join(f'<div class="it{" ev2" if k == "e" else ""}"><b>{esc(a)}</b>{esc(b)}</div>' for k, a, b in by.get(key, []))
        cols += f'<div class="col"><div class="dh">{key}<span>{names[i]}</span></div>{its or "<div class=none>—</div>"}</div>'
    return f'<div class="wk">{cols}</div><p class="sub" style="margin-top:8px"><span style="color:#2F7D4F">▌</span> Cổ tức, quyền &nbsp; <span style="color:#1F3366">▌</span> Sự kiện</p>'

def flow_card(title, f):
    mx = max([abs(v) for _, v in f["buy"] + f["sell"]] or [1])
    def rows(lst, cls):
        return "".join(f'<div class="r"><b>{esc(s)}</b><div><div class="bar {cls}" style="width:{max(4, abs(v)/mx*100):.0f}%"></div></div>'
                       f'<div class="v {"pos" if v>0 else "neg"}">{"+" if v>0 else "−"}{abs(v):,.0f}</div></div>'.replace(",", ".") for s, v in lst)
    return f'<div class="card fl"><h3>{esc(title)}</h3><div class="h">Mua ròng nhiều nhất (tỷ)</div>{rows(f["buy"], "b")}<div class="h">Bán ròng nhiều nhất (tỷ)</div>{rows(f["sell"], "s")}</div>'

def flows(d):
    f = d.get("flows")
    if not f: return ""
    return (f'<h2><span class="no">05</span> Dòng tiền phiên {esc(f.get("date",""))}</h2><p class="sub">Giá trị ròng, tỷ đồng</p>'
            f'<div class="grid g2">{flow_card("Khối ngoại", f["foreign"])}{flow_card("Tự doanh", f["prop"])}</div>')

def table(rows):
    tr = "".join(f"<tr><td>{esc(r[0])}</td><td>{esc(r[1])}</td><td>{esc(r[2])}</td></tr>" for r in rows)
    return f'<table class="ev"><tr><th>Ngày</th><th>Mã</th><th>Nội dung</th></tr>{tr}</table>'

def shell(d, body, k):
    return f"""<!doctype html><html lang="vi"><head><meta charset="utf-8"><style>{CSS}</style>
<style>{CSS_M}</style><style>.page .list p{{font-size:calc(19px*var(--k))}} .ev{{font-size:calc(18.5px*var(--k))}} .ev td{{padding:calc(10px*var(--k)) 6px}}</style></head>
<body><div class="page" style="--k:{k}">
<div class="top"><img src="data:image/png;base64,{LOGO}" alt="Weha"><div class="ed"><b>Bản tin sáng · 08:00</b>{esc(d["date_label"])}</div></div>
{body}
<div class="spacer"></div>
<div class="foot"><div class="who"><b>Nguyễn Hoài</b><br>Weha · 0396 336 096</div>
<div class="disc">Số liệu mang tính tham khảo, không phải khuyến nghị mua/bán. Nhà đầu tư tự chịu trách nhiệm với quyết định của mình.</div></div>
</div></body></html>"""

def page1(d):
    return f"""<span class="pill">Bản tin sáng</span>
<p class="brand">Trước giờ mở cửa · {esc(d["date_short"])} · Trang 1/2 — Vĩ mô</p>
<h1>{rich(d["headline"])}</h1>
<p class="lede">{rich(d["lede"])}</p>
<div class="strip mini">{"".join(tile(t) for t in d["strip"])}</div>
{hero(d)}
<h2><span class="no">01</span> Quốc tế</h2>
<p class="sub">{esc(d.get("intl_sub","% so với phiên trước"))}</p>
<div class="grid g5 mini">{"".join(tile(t) for t in d["intl_tiles"])}</div>
<div class="card list" style="margin-top:10px">{news(d["intl_news"])}</div>
<h2><span class="no">02</span> Trong nước</h2>
<p class="sub">Vĩ mô và chính sách mới</p>
<div class="grid g5 mini">{"".join(tile(t) for t in d["dom_tiles"])}</div>
<div class="card list" style="margin-top:10px">{news(d["dom_news"])}</div>"""

def page2(d):
    return f"""<span class="pill">Bản tin sáng</span>
<p class="brand">Trước giờ mở cửa · {esc(d["date_short"])} · Trang 2/2 — Doanh nghiệp & lịch sự kiện</p>
<h2 style="margin-top:6px;border-top:0;padding-top:0"><span class="no">03</span> Doanh nghiệp đáng chú ý</h2>
<p class="sub">Kết quả kinh doanh và tin mới</p>
<div class="card list">{news(d["company_news"])}</div>
<h2><span class="no">04</span> Lịch sự kiện</h2>
<p class="sub">Tuần này · giờ Việt Nam</p>
{week(d)}
{flows(d)}"""

async def render(d, out):
    from playwright.async_api import async_playwright
    async with async_playwright() as p:
        b = await p.chromium.launch()
        pg = await b.new_page(viewport={"width": 1080, "height": 1527}, device_scale_factor=2.3)
        files = []
        for i, fn in ((1, page1), (2, page2)):
            k = 1.0
            while True:
                path = os.path.join(out, f"Weha_ban_tin_sang_{d['file_date']}_trang{i}.html")
                open(path, "w", encoding="utf-8").write(shell(d, fn(d), k))
                await pg.goto("file://" + os.path.abspath(path)); await pg.wait_for_timeout(250)
                h = await pg.evaluate("document.querySelector('.page').scrollHeight")
                if h <= 1527 or k <= 0.8: break
                k = round(k - 0.03, 2)
            if h > 1527: print(f"CẢNH BÁO: trang {i} vẫn tràn ({h}px) — hãy bớt 1-2 dòng tin")
            png = path.replace(".html", ".png")
            await (await pg.query_selector(".page")).screenshot(path=png)
            files.append(png); print(f"trang {i}: chiều cao {h}px, hệ số chữ {k}")
        await b.close()
    return files

if __name__ == "__main__":
    d = json.load(open(sys.argv[1], encoding="utf-8"))
    out = sys.argv[2] if len(sys.argv) > 2 else "."
    os.makedirs(out, exist_ok=True)
    files = asyncio.run(render(d, out))
    for f in files: print(f)
    # Ghép 2 trang thành 1 PNG dọc (rộng 1800px) < 5 MB: out/YYYY-MM-DD.png
    from PIL import Image
    import datetime
    ngay = (datetime.datetime.utcnow() + datetime.timedelta(hours=7)).strftime("%Y-%m-%d")
    ims = []
    for f in files:
        im = Image.open(f).convert("RGB"); ims.append(im.resize((1800, round(im.height * 1800 / im.width)), Image.LANCZOS))
    canvas = Image.new("RGB", (1800, sum(i.height for i in ims)), "#F5F4ED"); y = 0
    for i in ims: canvas.paste(i, (0, y)); y += i.height
    fin = os.path.join(out, ngay + ".png"); canvas.save(fin, optimize=True)
    print("ANH_GHEP", fin, os.path.getsize(fin), "byte")
